presets.customCss:
/* Puff · 淡黄可爱 · 心声面板（配套聊天主题） */

.xs-panel {
  --xs-bg: rgba(255, 249, 219, 0.18);
  --xs-tile-bg: rgba(255, 249, 219, 0.22);
  --xs-text: #5a4a22;
  --xs-muted: #b8a46a;
  --xs-accent: #e8c860;
  --xs-border: rgba(230, 200, 110, 0.35);
  --xs-cap: #6b5a2e;
  --xs-action-bg: rgba(255, 243, 184, 0.45);
  --xs-done-bg: rgba(255, 243, 184, 0.55);
  background: rgba(255, 249, 219, 0.30);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

/* 顶栏 */
.xs-frame {
  width: min(380px, 100%);
}
.xs-cap-name {
  font-family: var(--display);
  font-size: 1.5rem;
  font-weight: 400;
  color: var(--xs-cap);
  letter-spacing: -0.01em;
  line-height: 1.1;
}
.xs-cap-time {
  font-size: 10px;
  color: var(--xs-muted);
  letter-spacing: 0.04em;
}
.xs-cap-x {
  border-radius: 999px;
  background: var(--xs-action-bg);
  border: 1px solid var(--xs-border);
  color: var(--xs-cap);
}

/* 操作按钮 */
.xs-actions {
  gap: 8px;
  margin-bottom: 12px;
}
.xs-action {
  border-radius: 999px;
  padding: 9px 12px;
  font-size: 12px;
  letter-spacing: 0.04em;
  background: var(--xs-action-bg);
  border: 1px solid var(--xs-border);
  color: var(--xs-cap);
}
.xs-action.is-on {
  background: rgba(245, 215, 110, 0.55);
  border-color: #e8c860;
}

/* 历史列表 */
.xs-history {
  border-radius: 16px;
  background: var(--xs-tile-bg);
  border: 1px solid var(--xs-border);
}
.xs-history-item {
  border-radius: 12px;
  color: var(--xs-text);
}
.xs-history-item.is-current {
  background: rgba(255, 243, 184, 0.55);
}
.xs-history-time {
  font-size: 10px;
  color: var(--xs-muted);
}
.xs-history-preview {
  font-size: 12px;
  line-height: 1.45;
}

/* 卡片拼盘 */
.xs-bento {
  gap: 10px;
}
.xs-tile {
  padding: 13px 14px 12px;
  border-radius: 14px;
  background: var(--xs-tile-bg);
  border: 1px solid var(--xs-border);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 2px 10px rgba(214, 178, 80, 0.08);
}
.xs-tile-k {
  font-size: 9px;
  font-weight: 500;
  color: var(--xs-muted);
  letter-spacing: 0.12em;
}
.xs-tile-v,
.xs-tile-lead {
  font-size: 12px;
  line-height: 1.55;
  color: var(--xs-text);
}

/* 卡片位 */
.xs-tile-thought {
  grid-column: 1 / -1;
}
.xs-tile-thought .xs-tile-lead {
  font-size: 13px;
  line-height: 1.65;
}
.xs-tile-deep {
  grid-column: 1 / -1;
  opacity: 0.92;
}

/* 好感数值 */
.xs-pulse-row {
  gap: 6px;
}
.xs-pulse-k {
  font-size: 9px;
  color: var(--xs-muted);
}
.xs-pulse-v {
  font-size: 12px;
  font-weight: 500;
  color: var(--xs-text);
}
.xs-pulse-v.is-up {
  color: #7fb87a;
}
.xs-pulse-v.is-down {
  color: #e08a7a;
}
.xs-pulse-v.is-flat {
  color: var(--xs-muted);
}

/* 加载 / 空态 / 关闭 */
.xs-loading-k {
  font-family: var(--display);
  font-size: 1.4rem;
  color: var(--xs-cap);
}
.xs-loading-v {
  font-size: 12px;
  color: var(--xs-muted);
}
.xs-empty-cards {
  font-size: 12px;
  color: var(--xs-muted);
}
.xs-done {
  margin-top: 18px;
  border-radius: 999px;
  padding: 11px;
  background: var(--xs-done-bg);
  font-size: 13px;
  color: var(--xs-cap);
}
